<template><view class="p"><view v-for="(q,i) in items" :key="i" class="q"><text>{{q.grammarTitle}}</text><text class="s">{{q.sentence}}</text><view v-for="o in q.options" :key="o" class="o" @click="answer(i,o)">{{o}}</view></view><view v-if="!items.length" class="e">暂无错题</view></view></template><script>export default{data(){return{items:[]}},onLoad(q){this.stage=Number(q.stage||0)},onShow(){this.items=(uni.getStorageSync('grammar_wrong')||[]).filter(q=>!this.stage||Number(q.stage)===this.stage)},methods:{answer(i,o){if(o===this.items[i].answer){this.items.splice(i,1);uni.setStorageSync('grammar_wrong',this.items);uni.showToast({title:'回答正确，已移除'})}else uni.showToast({title:'再想一想',icon:'none'})}}}</script><style>.p{min-height:100vh;background:#f7f5f0;padding:30rpx}.q{background:#fff;border-radius:16rpx;padding:28rpx;margin-bottom:20rpx;color:#1f3a5f;font-weight:bold}.s{display:block;color:#333;margin:20rpx 0}.o{padding:18rpx;border:1rpx solid #ddd;border-radius:10rpx;margin-top:12rpx;color:#333}.e{text-align:center;color:#888;padding:100rpx}</style>
